 *
 * ```text
 * object-id = 32*OCTET
 * ```
 */
public interface ObjectIdInterface {
    
    fun `toAddress`(): Address
    
    fun `toBytes`(): kotlin.ByteArray
    
    fun `toHex`(): kotlin.String
    
    companion object
}

